import { PLAYHEAD_LEAD_S, applyPlayRate, ensureLoopEls, loopEngineDispose, loopEngineSeek, loopEngineStart, loopEngineToggle, loopEpsS, loopEpsSet, nowTime, seekFrac, startTick, togglePlay, totalDur } from "../audio.js";
import { appBar, go, screenWrap } from "../router.js";
import { buildFormRail, lensBand, paintFormRail } from "../screens/chart.js";
import { S } from "../state.js";
import { NOTES, PREF, SERIF, SZ, T, UI, assignCost, clear, closeOverlay, ctlSkin, dispQ, el, glyph, handle, haptic, kitButton, kitIcon, kitSegmented, learnLevel, meanOf, mod, note, overlay, play, playGlyph, renderHand, renderKeys, renderVoicing, roleOf, rootHue, sheetBox, sheetCol, splitHands, vlCandidates, voClose, voicingByStyle, withBass } from "../ui/kit.js";

// The single DOM host div (`<div id="app">`) — there is exactly one call
// site, `window.APP.build(document.getElementById("app"))` in main.js, so
// every module that touches the screen host just looks it up itself rather
// than threading a mutable binding through every import (see sprint 16-19
// report: root/S design choice).
const root = document.getElementById("app");


  /* LE CLAVIER de Practise (T5 — Louis, 2026-08-19 : « il faut aussi afficher
     les accords au piano joliment si besoin »). Une carte de 74 px et rien
     d'autre : pas de titre de carte, pas de sélecteur de voicing, pas de
     légende — ces réglages vivent dans la feuille « ··· ». La fenêtre est
     celle de TOUT le morceau (l'union des deux mains, déjà calculée par
     handRanges.all) : elle ne se recadre jamais entre deux accords, et changer
     d'accord n'écrit que des couleurs.
     `card._show(midis)` est ce qu'appelle le changement d'accord. */
export function practiseKeyboard(rng){
    const KB_H=46;   // 74 − 12 de padding − 13 de ligne de noms − 3 de gap
    const card=el("div",`flex:0 0 auto;height:74px;margin:0 18px 10px;padding:6px;`+
      `background:${T.card};border:1px solid ${T.line};border-radius:12px;`+
      `display:flex;flex-direction:column;gap:3px;`);
    const head=el("div","flex:0 0 auto;display:flex;align-items:baseline;gap:8px;height:13px;");
    head.appendChild(el("div",
      `flex:0 0 auto;font:600 10px ${UI};letter-spacing:.06em;text-transform:uppercase;color:${T.faint};`,
      "au piano"));
    const names=el("div",`flex:1;min-width:0;text-align:right;font:600 11px ${UI};`+
      `overflow:hidden;text-overflow:ellipsis;white-space:nowrap;`);
    head.appendChild(names); card.appendChild(head);
    const kb=el("div",`flex:0 0 auto;height:${KB_H}px;`); card.appendChild(kb);
    const roles=new Map();
    // bâti TOUT DE SUITE, éteint : la carte n'est jamais un rectangle vide
    const light=renderHand(kb, [], KB_H, "chord", rng, {band:true, roles});
    card._show=midis=>{
      if(!midis || !midis.length){ clear(names); light([]); return; }
      const {left,right}=splitHands(midis);
      roles.clear();
      left.forEach(x=>roles.set(x,"bass")); right.forEach(x=>roles.set(x,"chord"));
      clear(names);
      names.appendChild(el("span",`color:${T.accent};`, left.map(x=>note(mod(x,12))).join(" ")));
      names.appendChild(el("span",`color:${T.faint};`," · "));
      names.appendChild(el("span","color:#2a6fb0;", right.map(x=>note(mod(x,12))).join(" ")));
      light(midis);
    };
    return card;
  }

  /* The card. TWO independent choices (Louis, 2026-08-08 — the first cut
     conflated them): WHAT you play — a two-hand voicing (left bass, right
     shapes) or a one-hand voicing (bass folded into the single hand) — and
     HOW it is drawn — one keyboard per hand, or both hands on one keyboard
     (the layout choice only exists for two hands).
     `getTwo()`/`getOne()` return the current voicings; card._repaint() on
     chord change only. `ranges` {lh, rh, all, oh} are the fixed per-song
     windows — see renderHand. */
export function buildHandsCard(getTwo, getOne, onPlay, ranges){
    let hands=(()=>{ try{ return localStorage.getItem("harmPrompterHands")==="1"?1:2; }catch(e){ return 2; } })();
    let split=(()=>{ try{ return localStorage.getItem("harmPrompterSplit")!=="0"; }catch(e){ return true; } })();

    const card=el("div",
      `width:min(100%,460px);background:${T.card};border:1px solid ${T.line};`+
      `border-radius:${SZ.radiusLg}px;padding:12px 12px 10px;margin-top:14px;cursor:pointer;`);
    // Louis, 2026-08-08 (iPhone): the two big segmenteds ate the screen — the
    // play button ended below the fold. They live in a PIANO SETUP sheet now,
    // behind one small button; the card is names + keyboards, nothing else.
    const head=el("div","display:flex;align-items:center;gap:8px;margin-bottom:8px;");
    const names=el("div",`flex:1;min-width:0;font:600 13px ${UI};color:${T.faint};min-height:16px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;`);
    head.appendChild(names);
    head.appendChild(kitButton("setup", openSetup, {small:true}));
    card.appendChild(head);
    function openSetup(){
      const back=overlay(); const sheet=sheetBox(); sheet.appendChild(handle());
      sheet.appendChild(el("div",`text-align:center;font:700 15px ${UI};color:${T.ink};margin-bottom:12px;`,"Piano"));
      const body=el("div","display:flex;flex-direction:column;gap:14px;");
      sheet.appendChild(body);
      function paintSheet(){
        clear(body);
        const row=(label,seg)=>{
          const r=el("div","display:flex;align-items:center;justify-content:space-between;gap:10px;");
          r.appendChild(el("span",`font:600 13px ${UI};color:${T.ink};`,label));
          r.appendChild(seg); return r;
        };
        body.appendChild(row("Hands", kitSegmented([[2,"Two"],[1,"One"]],
          ()=>hands,
          v=>{ hands=v; try{ localStorage.setItem("harmPrompterHands",String(v)); }catch(e){}
               paintSheet(); repaint(); },
          {inline:true, height:SZ.control, font:13})));
        if(hands===2){
          body.appendChild(row("Keyboards", kitSegmented([["split","One per hand"],["joined","One for both"]],
            ()=>split?"split":"joined",
            v=>{ split=(v==="split");
                 try{ localStorage.setItem("harmPrompterSplit", split?"1":"0"); }catch(e){}
                 paintSheet(); repaint(); },
            {inline:true, height:SZ.control, font:13})));
        }
      }
      paintSheet();
      const closeBtn=el("button",`width:100%;margin-top:14px;background:transparent;border:none;color:${T.faint};font:600 13px ${UI};padding:8px;min-height:${SZ.control}px;cursor:pointer;`,"Close");
      closeBtn.onclick=()=>closeOverlay(back);
      sheet.appendChild(closeBtn);
      back.appendChild(sheet); root.appendChild(back);
    }

    const body=el("div","display:flex;flex-direction:column;gap:9px;");
    card.appendChild(body);
    card.onclick=e=>{
      if(e.target.closest && e.target.closest("button")) return;
      const m=(hands===2?getTwo():getOne());
      if(m&&m.length&&onPlay) onPlay(m);
    };

    function row(tag, host){
      const r=el("div","display:flex;align-items:center;gap:9px;");
      r.appendChild(el("div",`flex:0 0 auto;width:26px;font:700 11px ${UI};letter-spacing:.08em;color:${T.faint};`,tag));
      host.style.flex="1"; r.appendChild(host);
      return r;
    }

    function repaint(){
      clear(body);
      if(hands===1){
        const midis=getOne()||[];
        if(!midis.length){ names.textContent=""; return; }
        names.textContent=midis.map(m=>note(m%12)).join(" ");
        const kb=el("div","");
        body.appendChild(row("", kb));
        const bass=Math.min(...midis), mp=new Map();
        midis.forEach(x=>mp.set(x,x===bass?"bass":"chord"));
        if(ranges&&ranges.oh) renderKeys(kb,mp,ranges.oh.lo,ranges.oh.oct,88,true);
        else renderVoicing(kb,midis,88,true);
        kb.style.flex="1";   // renderKeys' cssText reset drops it
        return;
      }
      const midis=getTwo()||[];
      if(!midis.length){ names.textContent=""; return; }
      if(split){
        const {left,right}=splitHands(midis);
        clear(names);
        const l=el("span",`color:${T.accent};`,"L "+left.map(m=>note(m%12)).join(" "));
        const r=el("span",`color:#2a6fb0;`,"R "+right.map(m=>note(m%12)).join(" "));
        names.appendChild(l); names.appendChild(el("span",""," · ")); names.appendChild(r);
        const rh=el("div",""), lh=el("div","");
        body.appendChild(row("R", rh));
        body.appendChild(row("L", lh));
        renderHand(rh, right, 64, "chord", ranges&&ranges.rh);
        renderHand(lh, left, 64, "bass", ranges&&ranges.lh);
        rh.style.flex="1"; lh.style.flex="1";   // renderHand's cssText reset drops it
      } else {
        names.textContent=midis.map(m=>note(m%12)).join(" ");
        const kb=el("div","");
        body.appendChild(row("", kb));
        // fixed whole-song window here too — renderVoicing would re-frame
        const bass=Math.min(...midis), mp=new Map();
        midis.forEach(x=>mp.set(x,x===bass?"bass":"chord"));
        if(ranges&&ranges.all) renderKeys(kb,mp,ranges.all.lo,ranges.all.oct,88,true);
        else renderVoicing(kb,midis,88,true);
        kb.style.flex="1";   // renderKeys' cssText reset drops it
      }
    }
    repaint();
    card._repaint=repaint;
    return card;
  }


  // ── persistent transport — LOCAL audio, survives screen re-renders ───────
  // ── PROMPTER (2026-08-05, Louis): the /compare karaoke reel (commit
  // b7fb411), moved into the app and re-skinned with the app's theme+glyphs.
  // Big current chord in the middle; at the bottom a roll of the NEXT TWO
  // BARS scrolling right→left past a fixed "now" marker. Data is
  // model.prompter.chords — the beat-grid re-decode captured BEFORE section
  // detection and folding touch anything (pipeline.prompter_chords); the
  // chart's own folded chords are only a fallback for old baked files.
  // Colours: root pitch class → circle-of-fifths hue (rootHue, the app's
  // convention everywhere), theme-aware tints; "Key colours" pref OFF falls
  // back to neutral card/ink like lensBand does.
export function reelFill(pc){
    if(!PREF.cof) return T.card;
    return PREF.theme==="dark" ? `hsl(${rootHue(pc)} 30% 28%)` : `hsl(${rootHue(pc)} 52% 84%)`;
  }
export function bigChordColor(pc){
    if(!PREF.cof) return T.ink;
    return PREF.theme==="dark" ? `hsl(${rootHue(pc)} 45% 74%)` : `hsl(${rootHue(pc)} 55% 34%)`;
  }
export function prompterData(){
    const m=S.model||{};
    if(m.prompter && m.prompter.chords && m.prompter.chords.length) return m.prompter.chords;
    // old baked chart without the key: flatten the chart's chords over every
    // pass — folded, but at least the reel works until the chart is re-baked
    return (S.chordTimeIndex||[]).map(h=>{ const c=S.chords[h.idx]||{};
      return {t0:h.t0, t1:h.t1, root:c.root||0, q:c.q||"", bass:(c.bass==null?-1:c.bass), nc:!!c.nc, c:(c.c==null?1:c.c)}; });
  }
export let _promptKeysBound=false;
export function renderPrompter(){
    const w=screenWrap();
    const m=S.model;
    if(!m){ setTimeout(()=>go("library",{push:false}),0); return w; }
    // T5 (2026-08-19) : la vitesse se LIT dans le sous-titre et se règle dans
    // la feuille — la rangée « SPEED » qui la portait a quitté l'écran.
    const RATES=[[0.5,"0.5×"],[0.75,"0.75×"],[1,"1×"]];
    const rateLbl=()=>{ const r=S.playRate||1; let best="1×", bd=9;
      RATES.forEach(([v,l])=>{ const d=Math.abs(v-r); if(d<bd){ bd=d; best=l; } }); return best; };
    const dots=kitIcon("···", ()=>openPractiseTools(), "Outils",
      {style:`border:1px solid ${T.accent};color:${T.accent};`});
    const topBar=appBar(m.title, "mesure 1 · "+rateLbl(), "chart", dots);
    const paintSub=()=>{ if(topBar._sub)
      topBar._sub.textContent="mesure "+Math.max(1,curBar>0?curBar:1)+" · "+rateLbl(); };
    w.appendChild(topBar);
    const chords=prompterData().slice().sort((a,b)=>a.t0-b.t0);
    const grid=(m.barGrid||[]).slice();
    ensureLoopEls();   // warm the loop pair so the first LOOP tap costs nothing
    // UI refresh 2026-08-08 (§4 / design 2a): current chord 78px, its ROLE on
    // one line under it, the next two chords greyed under that. The bar
    // counter moved to the reel's label; the "tap the piano…" micro-caption
    // is gone — the card is the affordance. The hands card + transport are
    // appended further down, after the voicing tracks they depend on.
    // Scrollable, not overflowing (Louis, 2026-08-08: the seam buttons were
    // visible but untappable — on a shorter viewport the centred stage
    // overflowed UNDER the reel block, whose transparent box then ate the
    // taps). auto-margins on first/last child: centred when there is room,
    // scrolls from the top when there is not.
    // T5 : plus AUCUN défilement vertical dans Practise. Ce qui rentrait par
    // le défilement rentre maintenant parce que la vitesse, le calage de seam,
    // le métronome et les réglages de piano sont partis dans la feuille.
    const stage=el("div","flex:1;min-height:0;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:0 18px;overflow:hidden;");
    const big=el("div","flex:0 0 auto;min-height:82px;display:flex;align-items:center;justify-content:center;");
    const sub=el("div",`font:italic 13px ${SERIF};color:${T.faint};margin-top:8px;min-height:17px;text-align:center;max-width:340px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;`,"");
    const nextRow=el("div","display:flex;align-items:baseline;gap:16px;margin-top:6px;min-height:26px;opacity:.42;");
    stage.appendChild(big); stage.appendChild(sub); stage.appendChild(nextRow);
    // A loop engaged on the CHART (A–B) is the same engine — adopt it, so the
    // loop button reads on and the seam adjuster is there (Louis's report:
    // "l'outil de calage n'est plus présent" after arming from the chart).
    let curMids=null, curOne=null,
        loop=S._loopEngine?{a:S._loopEngine.a, b:S._loopEngine.b}:null;
    // Deux mains ou une : le seul choix de voicing qui change ce que le clavier
    // de Practise DESSINE. (S.coachStyle, « le style de voicing » de la spec,
    // ne touche pas cet écran : le prompter voice avec sa propre cascade à
    // mouvement minimal, pas avec voicingByStyle. Un réglage inerte dans une
    // feuille vaut une ligne morte — il reste dans Aa, où il agit.)
    let hands2=(()=>{ try{ return localStorage.getItem("harmPrompterHands")==="1"?1:2; }catch(e){ return 2; } })();
    const kbMidis=()=>hands2===2?curMids:curOne;
    w.appendChild(stage);
    // no transport bar on this screen — the reel goes to the bottom edge
    const reelWrap=el("div","flex:0 0 auto;padding:0 18px 8px;");
    const reelInner=el("div","max-width:720px;margin:0 auto;");
    const reel=el("div",`position:relative;height:96px;background:${T.card};border:1px solid ${T.line};border-radius:14px;overflow:hidden;`);
    const strip=el("div","position:absolute;top:0;bottom:0;left:0;width:0;will-change:transform;");
    reel.appendChild(strip);
    const marker=el("div",`position:absolute;top:0;bottom:0;width:2px;background:${T.accent};z-index:5;box-shadow:0 0 8px ${T.accent}55;`);
    const markerCap=el("div",`position:absolute;top:2px;transform:translateX(-50%);color:${T.accent};font:700 10px ${UI};z-index:5;`,"▼");
    const markerLbl=el("div",`position:absolute;bottom:3px;color:${T.accent};font:600 8.5px ${UI};letter-spacing:.05em;opacity:.75;z-index:5;`,"now");
    reel.appendChild(marker); reel.appendChild(markerCap); reel.appendChild(markerLbl);
    reelInner.appendChild(reel);
    reelWrap.appendChild(reelInner); w.appendChild(reelWrap);
    // La bande de forme de T1, à 16px, tout en bas : elle dit où on est dans le
    // MORCEAU quand le reel ne montre que les quatre mesures qui viennent.
    // Même composant, même geste (tap = seek).
    // 14px sous la bande, pas 10 : c'est exactement la moitié tactile qui
    // dépasse SOUS une bande de 16 (44 − 16)/2. Sans ça la zone de tap sort de
    // l'écran par le bas, et un conteneur qui ne défile pas se met à défiler.
    const bandWrap=el("div","flex:0 0 auto;padding:0 0 calc(14px + env(safe-area-inset-bottom));");
    const band=buildFormRail({h:16});
    if(band){ band.style.paddingBottom="0"; bandWrap.appendChild(band); w.appendChild(bandWrap); }

    const MARKER_FRAC=0.18;
    // window ahead of the marker = exactly FOUR bars of this song
    const dbar=[]; for(let i=1;i<grid.length;i++) dbar.push(grid[i]-grid[i-1]);
    dbar.sort((a,b)=>a-b);
    const medBar=dbar.length?dbar[dbar.length>>1]:2.4;
    const aheadS=Math.max(3, 4*medBar);
    let W=0, markerX=0, pxs=0, blocks=[];
    const songDur=Math.max(grid.length?grid[grid.length-1]:0, chords.length?chords[chords.length-1].t1:1);
    const bigSize=74;   // T5: 74px, and the two next chords at 26px / .42
    function barAt(t){
      let lo=0, hi=grid.length-2, bi=0;
      while(lo<=hi){ const mid=(lo+hi)>>1; if(grid[mid]<=t){ bi=mid; lo=mid+1; } else hi=mid-1; }
      return bi;
    }
    // every prompter seek goes through here: inside an armed loop it moves
    // the ENGINE's element; a seek clearly outside the band disarms the loop
    // (you asked to leave), then seeks normally.
    function seekTo(t){
      if(loop){
        if(t>=loop.a-0.5 && t<=loop.b+0.5){ loopEngineSeek(t); sync(true); return; }
        loop=null; loopEngineDispose(true); paintLoop();
      }
      const d=totalDur(); if(d>0) seekFrac(t/d);
      sync(true);
    }
    function jumpBars(n){
      const target=Math.min(Math.max(barAt(nowTime()+PLAYHEAD_LEAD_S)+n,0),grid.length-2);
      seekTo(grid[target]);
    }
    function paintLoop(){
      const on=!!loop;
      loopBtn.style.background=on?T.accent:T.card; loopBtn.style.color=on?"#fff":T.ink;
      loopBtn.style.borderColor=on?T.accent:T.line;
      if(on) loopBars.textContent="bars "+(barAt(loop.a+0.01)+1)+"–"+(barAt(loop.b-0.01)+1);
      // le calage de seam vit dans la feuille « ··· » (T5) : si elle est
      // ouverte pendant qu'on arme la boucle, elle se repeint ; sinon rien.
      if(S._practiseSeamPaint) S._practiseSeamPaint();
    }
    // Two-hand voicings (Louis, 2026-08-05): left hand = the sounding bass
    // (F2–E3 window), right hand = the §9 minimal-movement cascade run over
    // the PROMPTER's chord stream with freeBass candidates — inversions and
    // rootless shapes allowed, since the left hand owns the bass.
    const lhMidi=c=>{ const pc=mod((c.bass!=null&&c.bass>=0)?c.bass:c.root,12);
      let b=36+pc; while(b<41) b+=12; return b; };
    const rhTrack=(()=>{
      const lv=learnLevel(), t=new Array(chords.length).fill(null);
      // "change as few NOTES as possible" (Louis, 2026-08-05): the primary
      // cost is the COUNT of keys that change (exact-midi common tones are
      // held); semitone movement only breaks ties. ×50 dominates any
      // in-window movement (≤ ~35 semitones).
      const changedKeys=(a,b)=>{
        const cnt={}; a.forEach(x=>cnt[x]=(cnt[x]||0)+1);
        let common=0; b.forEach(x=>{ if(cnt[x]>0){ common++; cnt[x]--; } });
        return Math.max(a.length,b.length)-common;
      };
      let prev=null;
      chords.forEach((c,i)=>{
        if(c.nc) return;
        const cands=vlCandidates(c.root,dispQ(c.q),lv,-1,true);
        let best=null,bc=Infinity;
        cands.forEach(cd=>{
          const cost=prev?changedKeys(prev.midis,cd.midis)*50+assignCost(prev.midis,cd.midis,false)
                         :Math.abs(meanOf(cd.midis)-66)+(cd.style==="close"?0:2);
          if(cost<bc){ bc=cost; best=cd; }
        });
        t[i]=best; prev=best;
      });
      // inspectable totals for the shipped track (read window.__prompterVL)
      try{
        let ch=0,mv=0,sp=0,pp=null;
        t.forEach(r=>{ if(!r) return;
          sp=Math.max(sp,Math.max.apply(null,r.midis)-Math.min.apply(null,r.midis));
          if(pp){ ch+=changedKeys(pp.midis,r.midis); mv+=assignCost(pp.midis,r.midis,true); } pp=r; });
        window.__prompterVL={changedKeys:ch, movedSemitones:Math.round(mv), maxSpanSemitones:sp};
      }catch(e){}
      return t;
    })();
    // ONE-hand voicings (Louis, 2026-08-08): the same minimal-movement
    // cascade, but bass-in-hand (freeBass off) — what a single hand really
    // plays. The two-hand track above keeps the left-hand-owns-the-bass
    // freedom.
    const ohTrack=(()=>{
      const lv=learnLevel(), t=new Array(chords.length).fill(null);
      let prev=null;
      chords.forEach((c,i)=>{
        if(c.nc) return;
        const cands=vlCandidates(c.root,dispQ(c.q),lv,(lv>=3)?c.bass:-1,false);
        let best=null,bc=Infinity;
        cands.forEach(cd=>{
          const cost=prev?assignCost(prev.midis,cd.midis,false)
                         :Math.abs(meanOf(cd.midis)-64)+(cd.style==="close"?0:4);
          if(cost<bc){ bc=cost; best=cd; }
        });
        t[i]=best; prev=best;
      });
      return t;
    })();
    // Fixed keyboard windows for the WHOLE song (Louis, 2026-08-05): the view
    // must never re-frame between chords, so each hand's range is the union
    // of everything it will play, computed once here — through the SAME
    // splitHands() the card uses per chord, so the windows always cover what
    // each keyboard is asked to show.
    const midsFor=(c,i)=>{
      const rh=rhTrack[i], lh=lhMidi(c);
      const rhM=rh?rh.midis:withBass(voClose(c.root,dispQ(c.q)),c.root,c.bass);
      return [lh].concat(rhM.filter(x=>x!==lh));
    };
    const oneFor=(c,i)=>{
      const oh=ohTrack[i];
      return oh?oh.midis:withBass(voClose(c.root,dispQ(c.q)),c.root,(learnLevel()>=3)?c.bass:-1);
    };
    const handRanges=(()=>{
      const span=a=>{ if(!a.length) return {lo:60,oct:2};
        const lo=12*Math.floor(Math.min.apply(null,a)/12);
        return {lo, oct:Math.max(1,Math.ceil((Math.max.apply(null,a)-lo+1)/12))}; };
      const L=[], R=[], A=[], O=[];
      chords.forEach((c,i)=>{ if(c.nc) return;
        const mids=midsFor(c,i), h=splitHands(mids);
        h.left.forEach(x=>L.push(x)); h.right.forEach(x=>R.push(x));
        mids.forEach(x=>A.push(x));
        oneFor(c,i).forEach(x=>O.push(x)); });
      return {lh:span(L), rh:span(R), all:span(A), oh:span(O)};
    })();
    // LE CLAVIER (T5). Il quitte le stage — c'est une zone à lui, sous le
    // stage, jamais dedans : la carte à deux claviers empilés faisait ~150px
    // et poussait le transport hors de l'écran. `S.piano==="never"` : la carte
    // n'est pas rendue du tout et ses 74px reviennent au stage.
    const kbCard = S.piano==="never" ? null : practiseKeyboard(handRanges.all);
    if(kbCard) w.insertBefore(kbCard, reelWrap);   // sous le stage, sur le reel
    // Big transport (design 2a): play 80 front and centre, four-bar jumps 60,
    // and a loop button that NAMES the bars it will cycle. It lives in the
    // FIXED bottom block, not the scrollable stage (Louis, 2026-08-08,
    // iPhone: "je ne vois même pas le bouton play une fois que c'est lancé")
    // — what you touch while playing never scrolls away.
    const ctrl=el("div","flex:0 0 auto;display:flex;align-items:center;justify-content:center;gap:14px;margin-bottom:10px;");
    const jumpStyle=`flex:0 0 auto;width:52px;height:52px;border-radius:50%;border:1px solid ${T.line};background:${T.card};color:${T.ink};font:600 15px ${UI};cursor:pointer;display:flex;align-items:center;justify-content:center;`;
    const back4=el("button",jumpStyle,"‹‹4"); back4.title="Back four bars (left arrow)";
    back4.onclick=()=>jumpBars(-4);
    const bigPlay=el("button",`flex:0 0 auto;width:64px;height:64px;border-radius:50%;border:none;background:${T.accent};color:#fff;font:600 26px ${UI};cursor:pointer;display:flex;align-items:center;justify-content:center;box-shadow:0 12px 28px -10px ${T.accent}aa;`);
    playGlyph(bigPlay, S.playing, 22);
    bigPlay.title="Play / pause (space)";
    bigPlay.onclick=()=>{ if(S._loopEngine) loopEngineToggle(); else togglePlay(); };
    const fwd4=el("button",jumpStyle,"4››"); fwd4.title="Forward four bars (right arrow)";
    fwd4.onclick=()=>jumpBars(4);
    const loopBtn=el("button",`flex:0 0 auto;height:52px;padding:0 14px;border-radius:${SZ.radiusLg}px;cursor:pointer;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;${ctlSkin("off")}`);
    const loopLbl=el("div",`font:700 13px ${UI};`,"loop");
    const loopBars=el("div",`font:500 11px ${UI};opacity:.75;`,"");
    loopBtn.appendChild(loopLbl); loopBtn.appendChild(loopBars);
    loopBtn.title="Loop the four-bar phrase you are in";
    loopBtn.onclick=()=>{
      if(loop){ loop=null; loopEngineDispose(true); }
      else{
        // snap to the 4-bar PHRASE grid (bars 0-3, 4-7, …) so the loop
        // cycles a musical unit, not four bars from wherever you happened
        // to press (Louis, 2026-08-05: "snap sur le grid de 4 barres")
        const g=Math.min(Math.floor(barAt(nowTime()+PLAYHEAD_LEAD_S)/4)*4, Math.max(0,grid.length-2));
        loop={a:grid[g], b:grid[Math.min(g+4,grid.length-1)]};
        loopEngineStart(loop.a,loop.b);
      }
      paintLoop();
    };
    ctrl.appendChild(back4); ctrl.appendChild(bigPlay); ctrl.appendChild(fwd4); ctrl.appendChild(loopBtn);
    // Le calage de seam (Louis, 2026-08-08 : « encore un poil trop tard, fais
    // moi un outil pour décaler à l'oreille ») est parti dans la feuille
    // « ··· » (T5). Il reste joignable dès qu'une boucle tourne, qu'elle ait
    // été armée ici ou depuis l'A–B du chart : la feuille lit `loop`, pas
    // l'écran d'où elle vient.
    const paintSeamVal=hostVal=>{ const ms=Math.round(loopEpsS*1000);
      hostVal.textContent = ms===0 ? "sur la barre" : Math.abs(ms)+" ms "+(ms>0?"en avance":"en retard"); };
    reelInner.appendChild(ctrl);   // le transport, sous le reel
    /* Ce qui a quitté l'écran de Practise et vit ici (T5) : la vitesse, le
       calage de la boucle, le métronome et le clavier. L'écran ne garde que ce
       qu'on touche en jouant — transport, reel, bande de forme. */
    function openPractiseTools(){
      const back=overlay(); const sheet=sheetCol(); sheet.appendChild(handle());
      const close=()=>{ S._practiseSeamPaint=null; closeOverlay(back); };
      sheet.appendChild(el("div",`flex:0 0 auto;text-align:center;font:700 15px ${UI};color:${T.ink};margin-bottom:2px;`,"Outils"));
      sheet.appendChild(el("div",`flex:0 0 auto;text-align:center;font:italic 12.5px ${SERIF};color:${T.faint};line-height:1.5;margin-bottom:12px;`,
        "on règle comment on joue, pas ce qu'on joue"));
      const body=el("div","flex:1 1 auto;overflow-y:auto;display:flex;flex-direction:column;gap:14px;");
      body.className="ap-scroll";
      sheet.appendChild(body);
      const row=(label,ctl)=>{
        const r=el("div","display:flex;align-items:center;justify-content:space-between;gap:10px;min-height:44px;");
        r.appendChild(el("div",`font:600 13px ${UI};color:${T.ink};`,label));
        r.appendChild(ctl); return r;
      };
      function paint(){
        clear(body);
        body.appendChild(row("Vitesse", kitSegmented(RATES,
          ()=>{ const r=S.playRate||1; let best=1,bd=9;
                RATES.forEach(([v])=>{ const d=Math.abs(v-r); if(d<bd){bd=d;best=v;} }); return best; },
          v=>{ S.playRate=v; applyPlayRate(); paintSub(); paint(); },
          {inline:true, height:SZ.control, font:13})));
        body.appendChild(row("Mains", kitSegmented([[2,"Deux"],[1,"Une"]],
          ()=>hands2,
          v=>{ hands2=v; try{ localStorage.setItem("harmPrompterHands",String(v)); }catch(e){}
               if(kbCard) kbCard._show(kbMidis()); paint(); },
          {inline:true, height:SZ.control, font:13})));
        body.appendChild(row("Piano", kitSegmented([["never","Jamais"],["tap","Au tap"],["follow","Suit"]],
          ()=>S.piano,
          v=>{ S.piano=v; S.coach=(v==="follow");
               try{ localStorage.setItem("harmPiano",v); localStorage.setItem("harmCoach",S.coach?"1":"0"); }catch(e){}
               close(); go("prompter",{push:false}); },   // la carte apparaît/disparaît
          {inline:true, height:SZ.control, font:13})));
        body.appendChild(row("Clic sur les accords", kitSegmented([["on","On"],["off","Off"]],
          ()=>S.metronome?"on":"off",
          v=>{ S.metronome=(v==="on"); try{ localStorage.setItem("harmMetronome",S.metronome?"1":"0"); }catch(e){} paint(); },
          {inline:true, height:SZ.control, font:13})));
        // Le calage de seam n'existe que pendant une boucle — armée ici ou
        // depuis l'A–B du chart, la feuille lit `loop` et ne sait pas d'où
        // elle vient (le bug de 2026-08-08 : « l'outil de calage n'est plus
        // présent » après un armement depuis le chart).
        if(loop){
          const val=el("span",`font:600 12px ${UI};color:${T.ink};min-width:104px;text-align:center;font-variant-numeric:tabular-nums;`,"");
          paintSeamVal(val);
          S._practiseSeamPaint=()=>paintSeamVal(val);
          const box=el("div","display:flex;align-items:center;gap:8px;");
          box.appendChild(kitButton("plus tôt", ()=>{ haptic(); loopEpsSet(Math.round(loopEpsS*1000)+4); paintSeamVal(val); }, {small:true}));
          box.appendChild(val);
          box.appendChild(kitButton("plus tard", ()=>{ haptic(); loopEpsSet(Math.round(loopEpsS*1000)-4); paintSeamVal(val); }, {small:true}));
          const blk=el("div","display:flex;flex-direction:column;gap:8px;");
          blk.appendChild(el("div",`font:600 13px ${UI};color:${T.ink};`,"Calage de la boucle"));
          blk.appendChild(el("div",`font:italic 12px ${SERIF};color:${T.faint};margin-top:-4px;`,
            "la reprise sonne en retard ? touche « plus tôt »"));
          blk.appendChild(box);
          body.appendChild(blk);
        }
      }
      paint();
      const cancel=el("button",`flex:0 0 auto;width:100%;margin-top:12px;background:transparent;border:none;`+
        `color:${T.faint};font:600 13px ${UI};padding:8px;min-height:${SZ.control}px;cursor:pointer;`,"Fermer");
      cancel.onclick=close;
      sheet.appendChild(cancel);
      back.onclick=e=>{ if(e.target===back) close(); };
      back.appendChild(sheet); root.appendChild(back);
    }
    if(loop) paintLoop();   // adopted from the chart's A–B — paint on arrival
    function layout(){
      W=reel.clientWidth; if(!W){ return; }
      markerX=Math.round(W*MARKER_FRAC); pxs=(W-markerX)/aheadS;
      marker.style.left=markerX+"px"; markerCap.style.left=markerX+"px"; markerLbl.style.left=(markerX+6)+"px";
      clear(strip); blocks=[];
      // bar lines first, then chord blocks on top
      for(let i=0;i<grid.length;i++){
        strip.appendChild(el("div",`position:absolute;top:0;bottom:0;left:${(grid[i]*pxs).toFixed(1)}px;width:1px;background:${T.rule};opacity:.45;`));
      }
      chords.forEach(c=>{
        const x0=c.t0*pxs, wpx=Math.max(3,(c.t1-c.t0)*pxs-2);
        const b=el("div",`position:absolute;top:50%;transform:translateY(-50%);height:62px;left:${x0.toFixed(1)}px;width:${wpx.toFixed(1)}px;border-radius:9px;display:flex;align-items:center;justify-content:center;overflow:hidden;white-space:nowrap;background:${c.nc?"transparent":reelFill(c.root)};border:1px solid ${c.nc?T.line:"transparent"};opacity:.62;`);
        if(c.nc) b.appendChild(el("span",`font:600 12px ${UI};color:${T.faint};`,"·"));
        else b.appendChild(glyph(c.root,c.q,18,"exact",T.ink,c.bass));
        strip.appendChild(b); blocks.push(b);
      });
      sync(true);
    }
    let curIdx=-2, curBar=-2, lastTx="";
    function chordAt(t){
      let lo=0, hi=chords.length-1, ans=-1;
      while(lo<=hi){ const mid=(lo+hi)>>1; if(chords[mid].t0<=t){ ans=mid; lo=mid+1; } else hi=mid-1; }
      return (ans>=0 && t<chords[ans].t1) ? ans : -1;
    }
    function sync(force){
      if(S.screen!=="prompter" || !pxs) return;
      const t=nowTime()+PLAYHEAD_LEAD_S;
      const tx=`translateX(${(markerX-t*pxs).toFixed(1)}px)`;
      if(tx!==lastTx){ strip.style.transform=tx; lastTx=tx; }
      const i=chordAt(t);
      if(i!==curIdx || force){
        if(curIdx>=0 && blocks[curIdx]){ const b=blocks[curIdx]; b.style.opacity=".62"; b.style.boxShadow="none"; b.style.height="62px"; }
        if(i>=0 && blocks[i]){ const b=blocks[i]; b.style.opacity="1"; b.style.boxShadow=`0 0 0 2px ${T.accent}`; b.style.height="78px"; b.style.zIndex="3"; }
        curIdx=i;
        clear(big); clear(nextRow);
        const c=i>=0?chords[i]:null;
        if(!c || c.nc){
          big.appendChild(el("div",`font-family:${SERIF};font-style:italic;font-weight:600;font-size:${Math.round(bigSize*0.55)}px;color:${T.faint};`,"N.C."));
          sub.textContent="";
          curMids=null; curOne=null;
          if(kbCard) kbCard._show(null);
        } else {
          big.appendChild(glyph(c.root,c.q,bigSize,"exact",bigChordColor(c.root),c.bass));
          // the ROLE on one line (design 2a) — same roleOf the editor's Guide uses
          const nx=(chords[i+1]&&!chords[i+1].nc)?{root:chords[i+1].root,q:chords[i+1].q}:null;
          sub.textContent=roleOf(S.key,c.root,dispQ(c.q),nx).text;
          // the next two chords, greyed
          [chords[i+1], chords[i+2]].forEach(n=>{ if(!n) return;
            nextRow.appendChild(n.nc
              ? el("span",`font:italic 600 16px ${SERIF};color:${T.faint};`,"N.C.")
              : glyph(n.root,n.q,26,"exact",T.ink,n.bass)); });
          curMids=midsFor(c,i);
          curOne=oneFor(c,i);
          if(kbCard) kbCard._show(kbMidis());
        }
      }
      // bar counter (1-based), from the same grid the chart's playhead uses —
      // shown on the reel's label since the role line took its old spot
      let lo=0, hi=grid.length-1, bi=-1;
      while(lo<=hi){ const mid=(lo+hi)>>1; if(grid[mid]<=t){ bi=mid; lo=mid+1; } else hi=mid-1; }
      const bar1=Math.min(Math.max(bi+1,1), m.nBars||grid.length-1);
      if(bar1!==curBar){ curBar=bar1;
        paintSub();
        if(!loop){
          const g=Math.min(Math.floor(Math.max(0,bi)/4)*4, Math.max(0,grid.length-2));
          loopBars.textContent="bars "+(g+1)+"–"+Math.min(g+4,Math.max(1,grid.length-1));
        }
      }
      // la bande de forme (T1) tient la position dans le morceau entier —
      // elle a remplacé la mini-timeline de 26px, et elle s'écrit sur l'horloge
      paintFormRail(t);
      // (the loop engine drives its own wrap now — v2, 2026-08-08)
      // big play button + keep the screen awake while playing
      if(S.playing!==lastPlaying){ lastPlaying=S.playing; playGlyph(bigPlay,S.playing,22); wakeLock(S.playing); }
    }
    let lastPh="", lastPlaying=null;
    async function wakeLock(on){
      try{
        if(on && !S._wakeLock && navigator.wakeLock) S._wakeLock=await navigator.wakeLock.request("screen");
        if(!on && S._wakeLock){ S._wakeLock.release(); S._wakeLock=null; }
      }catch(e){}
    }
    S._prompterSync=()=>sync(false);
    // Scroll animation: one transform write per frame, ONLY on this screen,
    // and skipped when the string is unchanged (paused). This is far lighter
    // than the 60/s full-DOM loop that starved iOS's audio engine (see the
    // startTick note); if the stall ever reappears, gate this on desktop.
    if(S._prompterRaf) cancelAnimationFrame(S._prompterRaf);
    const frame=()=>{ if(S.screen!=="prompter"){ S._prompterRaf=null; wakeLock(false); loopEngineDispose(true); return; } sync(false); S._prompterRaf=requestAnimationFrame(frame); };
    S._prompterRaf=requestAnimationFrame(frame);
    // Aucun défilement vertical dans Practise, jamais (acceptation T5). Si le
    // compte n'y est pas sur un écran court, c'est le REEL qui rétrécit
    // (96 → 80), jamais le clavier ni le stage.
    function fit(){
      reel.style.height="96px";
      if(w.scrollHeight > w.clientHeight+1) reel.style.height="80px";
    }
    requestAnimationFrame(fit);
    try{ new ResizeObserver(()=>layout()).observe(reel); }catch(e){ setTimeout(layout,0); }
    // reel: DRAG to scrub (grab the tape — right = earlier), plain tap = jump
    // to the tapped instant. touch-action pan-y leaves vertical scrolling to
    // the browser and horizontal gestures to us.
    reel.style.touchAction="pan-y";
    let dragX=null, dragT0=0, dragMoved=0, lastSeekTs=0;
    reel.addEventListener("pointerdown",e=>{
      dragX=e.clientX; dragT0=nowTime(); dragMoved=0;
      try{ reel.setPointerCapture(e.pointerId); }catch(err){}
    });
    reel.addEventListener("pointermove",e=>{
      if(dragX==null || !pxs) return;
      const dx=e.clientX-dragX; dragMoved=Math.max(dragMoved,Math.abs(dx));
      if(dragMoved>6){
        const now=performance.now();
        if(now-lastSeekTs>70){ lastSeekTs=now; seekTo(dragT0-dx/pxs); }
      }
    });
    const endDrag=e=>{
      if(dragX==null) return;
      if(dragMoved>6 && pxs) seekTo(dragT0-(e.clientX-dragX)/pxs);
      dragX=null;
    };
    reel.addEventListener("pointerup",endDrag);
    reel.addEventListener("pointercancel",()=>{ dragX=null; });
    reel.addEventListener("click",e=>{
      if(dragMoved>6){ dragMoved=0; return; }
      const r=reel.getBoundingClientRect();
      seekTo(nowTime()+PLAYHEAD_LEAD_S+((e.clientX-r.left)-markerX)/pxs);
    });
    // swipe DOWN anywhere (except the reel/strip, which own their gestures,
    // and the speed slider) = back to the chart — the bottom bar is gone, so
    // the screen needs a first-class way out
    let swY=null, swX=null;
    w.addEventListener("pointerdown",e=>{
      if(reel.contains(e.target)||((e.target.tagName||"")==="INPUT")) return;
      // a scrollable stage owns its vertical gesture — swiping there scrolls,
      // it must not yank the user back to the chart
      if(stage.contains(e.target) && stage.scrollHeight>stage.clientHeight+2) return;
      swY=e.clientY; swX=e.clientX;
    });
    w.addEventListener("pointerup",e=>{
      if(swY==null) return;
      const dy=e.clientY-swY, dx=e.clientX-swX; swY=null;
      if(dy>70 && dy>1.5*Math.abs(dx)) go("chart");
    });
    w.addEventListener("pointercancel",()=>{ swY=null; });
    // desktop keys: space = play/pause, ←/→ = four bars (bound once, screen-gated)
    S._prompterJump=jumpBars;
    if(!_promptKeysBound){ _promptKeysBound=true;
      document.addEventListener("keydown",e=>{
        if(S.screen!=="prompter") return;
        const tag=(e.target&&e.target.tagName)||"";
        if(tag==="INPUT"||tag==="TEXTAREA") return;
        if(e.code==="Space"){ e.preventDefault(); if(S._loopEngine) loopEngineToggle(); else togglePlay(); }
        else if(e.key==="ArrowLeft"){ e.preventDefault(); if(S._prompterJump) S._prompterJump(-4); }
        else if(e.key==="ArrowRight"){ e.preventDefault(); if(S._prompterJump) S._prompterJump(4); }
      });
    }
    return w;
  }

